"""Select and verify a Native hill-crest following route before actor spawn.

The 500 ft command needs more than 152.4 m of same-lane road.  Selection uses
Native waypoints, including grade, and refuses to relabel a flat road a crest.
"""
from __future__ import annotations

from math import hypot, isfinite


FEET_PER_METRE = 3.280839895013123


def _xy(waypoint):
    p = waypoint.transform.location
    return float(p.x), float(p.y), float(p.z)


def _lane(waypoint):
    return waypoint.road_id, waypoint.section_id, waypoint.lane_id


def route_from(start, *, target_gap_ft=500, step_m=5, runout_m=35):
    """Follow one connected lane and return an ego/apparatus crest pair.

    The selected pair has a centre separation beyond the requested body gap;
    the exact initial body gap is measured after actors are spawned.  Waypoint
    pitch is only a construction cue, never a visibility measurement.
    """
    if not isfinite(target_gap_ft) or target_gap_ft <= 0 or step_m <= 0:
        raise ValueError("Invalid route length or sampling step")
    needed = target_gap_ft / FEET_PER_METRE + runout_m
    chain = [start]
    distance = 0.0
    while distance < needed + 20:
        choices = [w for w in chain[-1].next(step_m)
                   if w.road_id == start.road_id and w.lane_id == start.lane_id
                   and not w.is_junction]
        if len(choices) != 1:
            raise ValueError("Following route needs one continuous nonjunction lane")
        next_waypoint = choices[0]
        a, b = _xy(chain[-1]), _xy(next_waypoint)
        segment = hypot(b[0] - a[0], b[1] - a[1])
        if segment < step_m * .5 or segment > step_m * 1.6:
            raise ValueError("Following route has a discontinuous lane sample")
        distance += segment
        chain.append(next_waypoint)
        if len(chain) > 1000:
            raise ValueError("Following route sample limit exceeded")
    grades = [_xy(chain[i + 1])[2] - _xy(chain[i])[2]
              for i in range(len(chain) - 1)]
    # Both sides of the crest must show at least 0.3 m change over three
    # samples. This is a map-shape check, not an evidentiary sight-line test.
    crest = next((i for i in range(3, len(chain) - 4)
                  if sum(grades[i-3:i]) > .3 and sum(grades[i:i+3]) < -.3), None)
    if crest is None:
        raise ValueError("Native lane has no measured hill crest")
    separation = target_gap_ft / FEET_PER_METRE
    apparatus_index = next((i for i, w in enumerate(chain)
                            if hypot(_xy(w)[0] - _xy(start)[0],
                                     _xy(w)[1] - _xy(start)[1]) >= separation), None)
    if apparatus_index is None or not (2 < crest < apparatus_index - 2):
        raise ValueError("Hill crest does not lie between following actors")
    return {"ego": start, "apparatus": chain[apparatus_index],
            "crest": chain[crest], "chain": chain,
            "road_id": start.road_id, "lane_id": start.lane_id,
            "sampled_distance_m": distance,
            "centre_separation_m": hypot(_xy(chain[apparatus_index])[0] - _xy(start)[0],
                                         _xy(chain[apparatus_index])[1] - _xy(start)[1])}


def select_crest_route(world_map, *, target_gap_ft=500, step_m=5):
    failures = []
    for spawn in world_map.get_spawn_points():
        waypoint = world_map.get_waypoint(spawn.location)
        if waypoint is None or waypoint.is_junction:
            continue
        try:
            return route_from(waypoint, target_gap_ft=target_gap_ft, step_m=step_m)
        except ValueError as error:
            failures.append(str(error))
    raise ValueError("No Native hill-crest route supports the following construction: "
                     + "; ".join(sorted(set(failures))))

"""Four original-frame RGB sources for the fire-apparatus delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer fire-alarm purpose or physical visibility from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8.0, 0.0, 8.0), (-12.0, 0.0, 0.0), (1920, 1080), 95),
    "approach": ((1.8, 0.0, 2.3), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-3.0, 2.5, 2.6), (-7.0, 0.0, 0.0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0.0, 0.0, 0.0), (1280, 720), 85),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans():
    return [CameraPlan(name, *spec) for name, spec in CAMERAS.items()]


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class FireCameraCapture:
    def __init__(self, world, carla_module, subject, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans():
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

"""Independent original-source audit for the fire-apparatus exact case.

This audits saved acquisition bytes and complete source-camera decoding.  It
cannot establish physical visibility or legal acceptance from a CPU fixture.
"""
from __future__ import annotations

import argparse
from hashlib import sha256
import importlib.util
import json
from pathlib import Path


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
REQUIRED = ("video_frames.jsonl", "trace.jsonl", "participant_footprints.jsonl",
            "participant_state.jsonl", "fire_context.json")


def _hash(path):
    return sha256(Path(path).read_bytes()).hexdigest()


def _rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def _finalizer():
    source = Path(__file__).with_name("fire_finalizer.py")
    spec = importlib.util.spec_from_file_location("fire_finalizer_audited", source)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def audit_attempt(attempt, report, *, decoder=None, receipt_dir=None):
    root = Path(attempt)
    report = json.loads(Path(report).read_text()) if not isinstance(report, dict) else report
    for name in (*REQUIRED, "config.json"):
        if not (root / name).is_file():
            raise ValueError("Missing audited original source: " + name)
    source_hashes = report["measurements"]["fire_boundary_observation"]["sources"]
    if set(source_hashes) != set(REQUIRED):
        raise ValueError("Analysis source inventory is incomplete or unexpected")
    if any(_hash(root / name) != expected for name, expected in source_hashes.items()):
        raise ValueError("Analysis source hash differs from retained acquisition")
    independent = _finalizer().analyze(root, write_channel=False)
    if independent["case_id"] != report["case_id"]:
        raise ValueError("Analysis case identity differs")
    if independent["measurements"] != report["measurements"]:
        raise ValueError("Analysis measurements differ from recomputed originals")
    frame_map = _rows(root / "video_frames.jsonl")
    trace = _rows(root / "trace.jsonl")
    if not frame_map or len(frame_map) != len(trace):
        raise ValueError("Original source frame count differs")
    for i, (mapping, row) in enumerate(zip(frame_map, trace)):
        if (mapping["video_frame"] != i or mapping["carla_frame"] != row["frame"]
                or mapping["time_s"] != row["time_s"]):
            raise ValueError("Original source frame identity differs")
    if decoder is None:
        from worker_exchange.media import audit as decoder
    if receipt_dir is not None:
        Path(receipt_dir).mkdir(parents=True, exist_ok=False)
    receipts = {}
    for camera in CAMERAS:
        path = root / (camera + ".mkv")
        if not path.is_file():
            raise ValueError("Missing named original camera: " + camera)
        receipt = None if receipt_dir is None else Path(receipt_dir) / (camera + "-decode.json")
        observed = decoder(path, len(frame_map),
                           mapping_sha256=_hash(root / "video_frames.jsonl"),
                           receipt=receipt)
        if observed.get("frames") != len(frame_map):
            raise ValueError("Named camera full decode frame count differs: " + camera)
        receipts[camera] = {"source_sha256": _hash(path), "decode": observed}
    return {"format": "worker-fire-source-audit", "case_id": report["case_id"],
            "original_source_hashes": source_hashes,
            "frame_count": len(frame_map), "camera_decodes": receipts,
            "measurement_recomputed": True, "physical_visibility_claimed": False,
            "legal_acceptance_claimed": False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--analysis", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    output = Path(args.output)
    if output.exists():
        raise ValueError("Retain previous audit receipt; choose a fresh output")
    receipt = audit_attempt(args.attempt, args.analysis,
                            receipt_dir=output.parent / (output.stem + "-decodes"))
    output.write_text(json.dumps(receipt, indent=2, allow_nan=False) + "\n")


if __name__ == "__main__":
    main()

import importlib.util
import json
import sys
import tempfile
import unittest
from pathlib import Path
from types import SimpleNamespace


folder = Path(__file__).resolve().parents[1]
runtime = folder.parents[1] / "runtime"
sys.path.insert(0, str(runtime))
sys.path.insert(0, str(runtime / "scenario_pipeline"))


def load(name):
    spec = importlib.util.spec_from_file_location(name, folder / (name + ".py"))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


session_module = load("fire_capture_session")
finalizer = load("fire_finalizer")


def point(x, y, z=0):
    return SimpleNamespace(x=x, y=y, z=z)


class Actor:
    def __init__(self, actor_id, x, direction):
        self.id, self.x, self.direction = actor_id, x, direction
        self.bounding_box = SimpleNamespace(get_world_vertices=self.vertices)

    def vertices(self, _):
        return [point(self.x + dx, dy, z) for dx in (-2, 2)
                for dy in (-1, 1) for z in (0, 1)]

    def get_transform(self):
        return SimpleNamespace(location=point(self.x, 0),
                               get_forward_vector=lambda: point(self.direction, 0))

    def get_velocity(self):
        return point(self.direction * 6, 0)

    def get_control(self):
        return SimpleNamespace(hand_brake=False)


class FakePipeline:
    def __init__(self, output, ego):
        self.output, self.ego = output, ego
        self.trace = (output / "trace.jsonl").open("x")

    def capture(self, frame, time_s):
        row = {"frame": frame, "time_s": time_s,
               "position_m": [self.ego.x, 0, 0]}
        self.trace.write(json.dumps(row) + "\n")
        self.trace.flush()
        return row

    def close(self):
        self.trace.close()


class FireCaptureSessionTests(unittest.TestCase):
    def test_original_tick_join_reaches_saved_measurement_both_directions(self):
        context = {"alarm_response_source": "authored dispatch premise",
                   "apparatus_answered_alarm": True,
                   "subject_authorized_emergency": False,
                   "subject_official_business": False}
        for direction in (1, -1):
            with self.subTest(direction=direction), tempfile.TemporaryDirectory() as temp:
                output = Path(temp)
                config = {"law_id": "NRS-484B-710", "selected_case_id": "fire-at-500",
                          "fire_branch": "traveling_follow"}
                (output / "config.json").write_text(json.dumps(config))
                ego = Actor(1, 0, direction)
                apparatus = Actor(2, direction * (4 + 500 / 3.280839895013123), direction)
                pipeline = FakePipeline(output, ego)
                try:
                    with session_module.FireCaptureSession(output, pipeline, ego, apparatus, context) as session:
                        for frame in (10, 11):
                            session.capture(frame, frame / 20,
                                            warning_lamp_readback=True,
                                            siren_readback=True)
                            ego.x += direction
                            apparatus.x += direction
                finally:
                    pipeline.close()
                report = finalizer.analyze(output)
                self.assertEqual(report["measurements"]["fire_boundary_observation"]
                                 ["value"]["active_frame_count"], 2)

    def test_missing_readback_rejected_before_pipeline_capture(self):
        context = {"alarm_response_source": "authored dispatch premise",
                   "apparatus_answered_alarm": True,
                   "subject_authorized_emergency": False,
                   "subject_official_business": False}
        with tempfile.TemporaryDirectory() as temp:
            output = Path(temp)
            ego, apparatus = Actor(1, 0, 1), Actor(2, 150, 1)
            pipeline = FakePipeline(output, ego)
            try:
                with session_module.FireCaptureSession(output, pipeline, ego, apparatus, context) as session:
                    with self.assertRaisesRegex(ValueError, "Warning lamp requires"):
                        session.capture(10, .5, warning_lamp_readback=None,
                                        siren_readback=True)
                self.assertEqual((output / "trace.jsonl").read_text(), "")
            finally:
                pipeline.close()


if __name__ == "__main__":
    unittest.main()
